This three-color DFS cycle check runs on a directed graph with a cycle 1 -> 2 -> 3 -> 1. What does it print?
g = {0: [1], 1: [2], 2: [3], 3: [1]}
color = {u: 0 for u in g}
def dfs(u):
    color[u] = 1
    for v in g[u]:
        if color[v] == 1 or (color[v] == 0 and dfs(v)): return True
    color[u] = 2
print(dfs(0), color)

This lazy Dijkstra counts heap pops. What does it print (distance to vertex 3, number of pops)?
import heapq
g = {0: [(1, 1), (2, 4)], 1: [(2, 2), (3, 6)], 2: [(3, 3)], 3: []}
d, h, pops = {0: 0}, [(0, 0)], 0
while h:
    w, u = heapq.heappop(h); pops += 1
    if w > d[u]: continue
    for v, c in g[u]:
        if w + c < d.get(v, 99): d[v] = w + c; heapq.heappush(h, (w + c, v))
print(d[3], pops)

This BFS counts shortest paths from vertex 0. What does it print?
from collections import deque
g = {0: [1, 2], 1: [3], 2: [3], 3: [4], 4: []}
dist, ways, q = {0: 0}, {0: 1}, deque([0])
while q:
    u = q.popleft()
    for v in g[u]:
        if v not in dist: dist[v] = dist[u] + 1; ways[v] = 0; q.append(v)
        if dist[v] == dist[u] + 1: ways[v] += ways[u]
print(ways[4])

What does this Kruskal code print?
edges = [(1, 'A', 'B'), (2, 'B', 'C'), (3, 'A', 'C'), (4, 'C', 'D'), (5, 'B', 'D')]
p = {x: x for x in 'ABCD'}
def find(x): return x if p[x] == x else find(p[x])
tot = 0
for w, u, v in sorted(edges):
    if find(u) != find(v): p[find(u)] = find(v); tot += w
print(tot)

What does this DFS with timestamps print (discovery time of c, finish time of a)?
g = {'a': ['b', 'c'], 'b': ['c'], 'c': []}
t, d, f = 0, {}, {}
def dfs(u):
    global t
    t += 1; d[u] = t
    for v in g[u]:
        if v not in d: dfs(v)
    t += 1; f[u] = t
dfs('a'); print(d['c'], f['a'])

An iterative DFS pushes each unvisited neighbor onto a stack and marks it visited at push time. What does this code print?
g = {1: [2, 3], 2: [4], 3: [4], 4: []}
st, seen, out = [1], {1}, []
while st:
    u = st.pop(); out.append(u)
    for v in g[u]:
        if v not in seen: seen.add(v); st.append(v)
print(out)
